import math

CART_FORCE_LIMIT_NEWTONS = 450.0
INITIAL_REF_TRACK_CENTER_X = 50.0  # Corrected to new environment's track center

def build_agent(sandbox):
    return sandbox.get_cart_body()

def agent_action(sandbox, agent_body, step_count):
    theta = sandbox.get_pole_angle()
    omega = sandbox.get_pole_angular_velocity()
    x, v = sandbox.get_cart_position(), sandbox.get_cart_velocity()
    target_x = INITIAL_REF_TRACK_CENTER_X
    margin = sandbox.SAFE_HALF_RANGE  # 8.5 m

    # Proactive boundary correction with velocity-based threshold
    if abs(x - target_x) > 8.0:  # Proactive boundary correction threshold (8.0m from center)
        if x > target_x + margin:
            # Right edge approaching
            if abs(v) < 10.0:  # Only apply if velocity is low to avoid overshoot
                boundary_term = -50.0 * (x - (target_x + margin)) - 25.0 * v
            else:
                boundary_term = 0.0
        elif x < target_x - margin:
            # Left edge approaching
            if abs(v) < 10.0:
                boundary_term = 50.0 * (target_x - margin - x) - 25.0 * v
            else:
                boundary_term = 0.0
        else:
            boundary_term = 0.0
    else:
        boundary_term = 0.0

    # Control gains for stability (reduced to prevent overcorrection)
    force = -300.0 * theta - 75.0 * omega - 50.0 * (x - target_x) - 30.0 * v

    # Add boundary correction term
    force += boundary_term

    # Clamp force within actuator limits
    lim = CART_FORCE_LIMIT_NEWTONS
    sandbox.apply_cart_force(max(-lim, min(lim, force)))

